<?php require '../includes/functions.php';require_admin();if(isset($_GET['action'],$_GET['id'])){$id=intval($_GET['id']);$a=$_GET['action'];if($a==='resolve')$pdo->prepare("UPDATE reports SET status='resolved' WHERE id=?")->execute([$id]);if($a==='hide')$pdo->prepare("UPDATE reports SET status='hidden' WHERE id=?")->execute([$id]);if($a==='open')$pdo->prepare("UPDATE reports SET status='open' WHERE id=?")->execute([$id]);flash('Estado actualizado.');header('Location: '.url('admin/index.php'));exit;}$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM reports) reports,(SELECT COUNT(*) FROM comments) comments,(SELECT COUNT(*) FROM reports WHERE status='resolved') resolved")->fetch();$rs=$pdo->query('SELECT r.*,u.name FROM reports r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC')->fetchAll();$us=$pdo->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY created_at DESC LIMIT 10')->fetchAll();$title='Administración';require '../includes/header.php';?><main class="dashboard"><div class="welcome"><div><h1>Panel de administración</h1><p class="muted">Moderación, usuarios y seguimiento del servicio.</p></div></div><div class="stats"><div class="stat"><span>Usuarios</span><b><?=$stats['users']?></b></div><div class="stat"><span>Reportes</span><b><?=$stats['reports']?></b></div><div class="stat"><span>Comentarios</span><b><?=$stats['comments']?></b></div><div class="stat"><span>Casos resueltos</span><b><?=$stats['resolved']?></b></div></div><div class="panel"><h2>Gestión de reportes</h2><div style="overflow:auto"><table><tr><th>ID</th><th>Publicación</th><th>Usuario</th><th>Tipo</th><th>Estado</th><th>Acciones</th></tr><?php foreach($rs as $r):?><tr><td>#<?=$r['id']?></td><td><a href="<?=url('reports/view.php?id='.$r['id'])?>"><b><?=e($r['title'])?></b></a></td><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><?=$r['status']==='resolved'?'Resuelto':($r['status']==='open'?'Activo':'Oculto')?></td><td><a href="?action=resolve&id=<?=$r['id']?>">Resolver</a> · <a class="danger" href="?action=hide&id=<?=$r['id']?>">Ocultar</a> · <a href="?action=open&id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;?></table></div></div><div class="panel" style="margin-top:20px"><h2>Usuarios recientes</h2><table><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Registro</th></tr><?php foreach($us as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=date('d/m/Y',strtotime($u['created_at']))?></td></tr><?php endforeach;?></table></div></main><?php require '../includes/footer.php';?>